def group_by_key(data: list[dict], key: str) -> dict:
    """Group a list of dictionaries by the value of a given key.

    Args:
        data: List of dictionaries to group.
        key: The key to group by.

    Returns:
        A dictionary where keys are the unique values of the given key
        and values are lists of dictionaries with that key value.

    Example:
        >>> data = [{'category': 'A', 'value': 1}, {'category': 'B', 'value': 2}, {'category': 'A', 'value': 3}]
        >>> group_by_key(data, 'category')
        {'A': [{'category': 'A', 'value': 1}, {'category': 'A', 'value': 3}], 'B': [{'category': 'B', 'value': 2}]}
    """
    if not isinstance(data, list):
        raise ValueError("data must be a list")
    if not all(isinstance(item, dict) for item in data):
        raise ValueError("all items in data must be dictionaries")
    if not key:
        raise ValueError("key must be a non-empty string")

    grouped = {}
    for item in data:
        if key not in item:
            raise ValueError(f"key '{key}' not found in item {item}")
        value = item[key]
        if value not in grouped:
            grouped[value] = []
        grouped[value].append(item)
    return grouped
